	["{npc:3412}'s workshop is in the {object:172958} beside {npc:4485}: hand in {quest:2841} if you ran {area:133}."] = "Die Werkstatt von {npc:3412} ist im {object:172958} neben {npc:4485}: Gib {quest:2841} ab, wenn du {area:133} gemacht hast.",

	-- Step 44: Orgrimmar trainers
	-- {zone:1454} Orgrimmar
	["{zone:1454} trainers"] = "Lehrer in {zone:1454}",
	-- {zone:1458} Undercity
	["Train while you are in the city; everyone else trains in the {zone:1458}, next."] = "Lerne, solange du in der Stadt bist; alle anderen lernen als Nächstes in der {zone:1458}.",
	-- {zone:1458} Undercity
	["The next guide takes the {zone:1458} zeppelin from the tower outside the main gate."] = "Der nächste Guide nimmt den Zeppelin der {zone:1458} vom Turm vor dem Haupttor.",

	-- No longer in the guide (its English changed or it went away): reuse or delete.
	-- ["Darkfang spiders"] = "Dunkelzahnspinnen",
	-- ["Darkmist cavern"] = "Höhle der Darkmist",
	-- ["For {npc:2519} at {object:3202}, in the next guide"] = "Für {npc:2519} in {object:3202}, im nächsten Guide",
	-- ["Head back west to Brackenwall with the head."] = "Geh mit dem Kopf zurück nach Westen nach Brackenwall.",
	-- ["Head back west to Brackenwall with the head: {npc:4503} stands at the south edge of the village where the road comes in, {npc:4791} in the village."] = "Geh mit dem Kopf zurück nach Westen nach Brackenwall: {npc:4503} steht am Südrand des Dorfes, wo die Straße hereinkommt, {npc:4791} im Dorf.",
	-- ["Head east back to the {area:497}."] = "Geh nach Osten zurück zum {area:497}.",
	-- ["Head east to {area:602}. Use the Rod of Banishing by each demon portal to close six of them."] = "Geh nach Osten zu {area:602}. Benutze den Rod of Banishing an jedem Dämonenportal, um sechs davon zu schließen.",
	-- ["Head north to {npc:5412} at {area:597}."] = "Geh nach Norden zu {npc:5412} bei {area:597}.",
	-- ["Head north up the road to the hut by the road north of the graveyard."] = "Geh die Straße nach Norden zur Hütte an der Straße nördlich des Friedhofs.",
	-- ["Head north-east to the {area:607}. {npc:12277} is held in the Maraudine centaur camp; free her and escort her out east of the valley."] = "Geh nach Nordosten zum {area:607}. {npc:12277} wird im Lager der Maraudine-Zentauren festgehalten; befreie sie und eskortiere sie östlich aus dem Tal.",
	-- ["Head on south-west to Shadowprey."] = "Geh weiter nach Südwesten zur Schattenbeute.",
	-- ["Head south from {area:2405} into the {area:607}. The Maraudine Scouts, Wranglers, Maulers, Windchasers and Marauders (36-39) drop the {quest:93225}."] = "Geh von {area:2405} nach Süden ins {area:607}. Die Späher, Treiber, Zermalmer, Windjäger und Marodeure der Maraudine (36-39) lassen {quest:93225} fallen.",
	-- ["Head south-east from the coven to the bone fields of the {area:2657}, where Undead Ravagers roam. At the far south-east, use the {item:15848} to draw the Magrami Spectres: they drop the ghost-o-plasm."] = "Geh vom Hexenzirkel nach Südosten zu den Knochenfeldern des {area:2657}, wo Untote Verheerer umherstreifen. Benutze ganz im Südosten {item:15848}, um die Schreckgespenster der Magram anzulocken: Sie lassen das Geisterplasma fallen.",
	-- ["Head south-east to the bone fields of the {area:2657}, where Undead Ravagers roam, at {zone:1443}'s southern edge. Use the {item:15848} at the arrow to draw the Magrami Spectres: they drop the ghost-o-plasm.\nCareful: Magram Necrokhans and Corpsefeeders (45, elite) walk the bone fields just west of the arrow, well above you: use the crate at the arrow, on the valley's eastern side, and pull the spectres away from them."] = "Geh nach Südosten zu den Knochenfeldern des {area:2657}, wo Untote Verwüster umherstreifen, am Südrand von {zone:1443}. Benutze die {item:15848} am Pfeil, um die Magrami-Gespenster anzulocken: Sie lassen das Ghost-o-Plasma fallen.\nVorsicht: Nekrokhane und Leichenfresser der Magram (45, Elite) laufen über die Knochenfelder direkt westlich des Pfeils, weit über deiner Stufe: Benutze die Kiste am Pfeil, auf der Ostseite des Tals, und zieh die Gespenster von ihnen weg.",
	-- ["Head west back across the marsh. The Darkfang Venomspitters on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely."] = "Geh westlich zurück durch den Sumpf. Die Dunkelzahngiftspucker auf den Kämmen nördlich von Brackenwall lassen die Giftdrüsen fallen. Spitzel von Theramore (35-36) schleichen durch dieselben Wälder: Sie sind getarnt, sieh also genau hin.",
	-- ["Head west back across the marsh. The Darkfang Venomspitters on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely.\nThe Darkmist spiders swarm the cavern mouth north-west of Brackenwall; every kind drops eyes.\nCareful: Darkfang Lurkers (level 36-37) use Sneak to stealth while out of combat and cast Poison once fighting.\nCareful: Stealthed spiders in the same area will attack you on sight.\nCareful: Darkmist Lurkers move about stealthed and use poison once in combat. The spiders stand close together, so adds are common; pulling single targets from the outer edge cuts down on them."] = "Geh nach Westen zurück über den Sumpf. Die Giftspucker der Darkfang auf den Kämmen nördlich von Brackenwall lassen die Giftbeutel fallen. Infiltratoren von Theramore (35-36) schleichen durch dieselben Wälder: Sie sind getarnt, also sieh genau hin.\nDie Spinnen der Darkmist schwärmen am Höhleneingang nordwestlich von Brackenwall; jede Art lässt Augen fallen.\nVorsicht: Darkfang-Lauerer (Stufe 36-37) benutzen Schleichen, um außerhalb des Kampfes getarnt zu bleiben, und wirken im Kampf Gift.\nVorsicht: Getarnte Spinnen im selben Gebiet greifen dich auf Sicht an.\nVorsicht: Darkmist-Lauerer bewegen sich getarnt und benutzen im Kampf Gift. Die Spinnen stehen dicht beieinander, daher sind Adds häufig; einzelne Ziele vom äußeren Rand zu ziehen verringert sie.",
	-- ["Head west to {npc:11863}'s tower at {area:2405} on the north-west coast."] = "Geh nach Westen zum Turm von {npc:11863} bei {area:2405} an der Nordwestküste.",
	-- ["Hearth to Shadowprey"] = "Ruhestein nach Shadowprey",
	-- ["Hearth to {area:392}"] = "Ruhestein nach {area:392}",
	-- ["Kodo bones"] = "Kodoknochen",
	-- ["Kodo bones and ghosts"] = "Kodoknochen und Geister",
	-- ["Level 37.5"] = "Stufe 37,5",
	-- ["Maraudine totems"] = "Totems der Maraudine",
	-- ["North to the goblin camp on the west side of the {area:596}."] = "Nach Norden zum Goblinlager auf der Westseite des {area:596}.",
	-- ["North to the post; {npc:5412} stands beside {npc:5395}."] = "Nach Norden zum Posten; {npc:5412} steht neben {npc:5395}.",
	-- ["Pick up the kodo bones scattered across the graveyard, and use the {item:15848} among the bones: the ghosts it draws drop the ghost-o-plasm."] = "Sammle die über den Friedhof verstreuten Kodoknochen und benutze die {item:15848} zwischen den Knochen: Die angelockten Geister lassen das Geisterplasma fallen.",
	-- ["Pick up the kodo bones scattered across the graveyard."] = "Sammle die über den Friedhof verstreuten Kodoknochen ein.",
	-- ["Ride back west to Brackenwall with the head."] = "Reite mit dem Kopf zurück nach Westen nach Brackenwall.",
	-- ["Ride east back to the {area:497}."] = "Reite nach Osten zurück zum {area:497}.",
	-- ["Ride east from {area:378} along the road into the marsh. The burned-out {area:403} stands beside it just past the border; the shield, the badge and the hoofprints are in and beside the ruin."] = "Reite von {area:378} die Straße entlang nach Osten in die Marschen. Das ausgebrannte {area:403} steht gleich hinter der Grenze daneben; der Schild, die Plakette und die Hufspuren sind in und neben der Ruine.",
	-- ["Ride east to {area:602}. Use the Rod of Banishing by each demon portal to close six of them."] = "Reite nach Osten zu {area:602}. Benutze den Rod of Banishing an jedem Dämonenportal, um sechs davon zu schließen.",
	-- ["Ride north from the coven to {npc:5412} at {area:597}."] = "Reite vom Koven nach Norden zu {npc:5412} am {area:597}.",
	-- ["Ride north to {area:502}. Stinky stands at the foot of the hill; escort him while he gathers Bogbean Leaves just south of it."] = "Reite nach Norden zum {area:502}. Stinki steht am Fuß des Hügels; eskortiere ihn, während er gleich südlich davon Blätter von Sumpfbohnenpflanzen sammelt.",
	-- ["Ride north up the road to the hut by the road north of the graveyard."] = "Reite die Straße hinauf nach Norden zur Hütte an der Straße nördlich des Friedhofs.",
	-- ["Ride north-east to the {area:607}. {npc:12277} is held in the Maraudine centaur camp; free her and escort her out east of the valley."] = "Reite nach Nordosten ins Tal ({area:607}). {npc:12277} wird im Zentaurenlager der Maraudine festgehalten; befreie sie und eskortiere sie nach Osten aus dem Tal hinaus.",
	-- ["Ride on south-west to Shadowprey."] = "Reite weiter nach Südwesten nach Shadowprey.",
	-- ["Ride south from {area:2405} into the {area:607}. The Maraudine Scouts, Wranglers, Maulers, Windchasers and Marauders (36-39) drop the {quest:93225}."] = "Reite von {area:2405} nach Süden ins Tal ({area:607}). Die Späher, Zänker, Raufer, Windhetzer und Marodeure der Maraudine (36-39) lassen {quest:93225} fallen.",
	-- ["Ride west back across the marsh. The Darkfang Venomspitters on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely."] = "Reite nach Westen zurück durch die Marschen. Die Dunkelzahngiftspucker auf den Kämmen nördlich von Brackenwall lassen die Giftbeutel fallen. Spitzel von Theramore (35-36) schleichen durch dieselben Wälder: Sie sind getarnt, also schau genau hin.",
	-- ["Ride west to {npc:11863}'s tower at {area:2405} on the north-west coast."] = "Reite nach Westen zum Turm von {npc:11863} in {area:2405} an der Nordwestküste.",
	-- ["Slitherblade coast"] = "Küste der Zackenkämme",
	-- ["South-east from the manor to {area:513}: the {object:20925} lies on the sea floor off the docks on the isle's east side. Swim in and out and keep off the piers and the town: Theramore's guards are level 53-57, and a death here is a long run back from the spirit healer."] = "Vom Gutshaus nach Südosten zu {area:513}: {object:20925} liegt auf dem Meeresgrund vor den Docks an der Ostseite der Insel. Schwimm hinein und wieder hinaus und halte dich von den Piers und der Stadt fern: Die Wachen von Theramore sind Stufe 53-57, und ein Tod hier bedeutet einen langen Weg zurück vom Geistheiler.",
	-- ["The Burning Blade hold the fortress north-west of {area:2407}. Use the {item:14523} on the {npc:11876} in the fortress to get the {item:13542}."] = "Die Burning Blade hält die Festung nordwestlich von {area:2407}. Benutze {item:14523} an {npc:11876} in der Festung, um {item:13542} zu bekommen.",
	-- ["The Darkmist spiders swarm the cavern mouth north-west of Brackenwall; every kind drops eyes."] = "Die Graunebelspinnen wimmeln am Höhleneingang nordwestlich von Brackenwall; jede Art lässt Augen fallen.",
	-- ["The Slitherblade naga hold the coast north of {area:2405}, up to {area:598}. {npc:12369} guards the {quest:6027} at the far northern tip."] = "Die Naga der Zackenkämme halten die Küste nördlich von {area:2405} bis zum {area:598}. {npc:12369} bewacht {quest:6027} an der äußersten Nordspitze.",
	-- ["The caravan ends at {npc:11596}'s camp on the east side of the {area:596}."] = "Die Karawane endet in {npc:11596}s Lager auf der Ostseite des Friedhofs ({area:596}).",
	-- ["The next guide takes you back to {zone:1434}."] = "Der nächste Guide bringt dich zurück ins {zone:1434}.",
	-- ["West of the post, the Maraudine centaurs hold the {area:607}. Every Maraudine can drop a {item:254432} and an ear for {npc:5395}'s {quest:1366}. Stay with the Maraudine (36-39) in the valley: the Magram's village in the south-east has the same drops, but its Necromancers (42-43) and Guardians (39-41) are well above you."] = "Westlich des Postens halten die Zentauren der Maraudine das {area:607}. Jeder Maraudine kann ein {item:254432} und ein Ohr für die {quest:1366} von {npc:5395} fallen lassen. Bleib bei den Maraudine (36-39) im Tal: Das Dorf der Magram im Südosten hat dieselbe Beute, aber seine Nekromanten (42-43) und Wächter (39-41) sind weit über deiner Stufe.",
	-- ["West to Shadowprey."] = "Nach Westen nach Shadowprey.",
	-- ["grind on {npc:4377}"] = "grinde an {npc:4377}",
	-- ["{npc:11624} stands in the village."] = "{npc:11624} steht im Dorf.",
	-- ["{npc:11626}'s caravan stops on the road at the edge of {area:602}. Escort it east past the coven; demons attack it twice."] = "Die Karawane von {npc:11626} hält auf der Straße am Rand von {area:602}. Eskortiere sie nach Osten am Koven vorbei; Dämonen greifen sie zweimal an.",
	-- ["{npc:3391}: for {npc:4631} in {area:35}, on the first {area:35} stop of 40-50"] = "{npc:3391}: für {npc:4631} in {area:35}, beim ersten Halt in {area:35} in 40-50",
	-- ["{npc:4983} waits in the {area:2302} east of the village. Follow him to Reethe and keep him alive through the fight that breaks out."] = "{npc:4983} wartet im Morast ({area:2302}) östlich des Dorfs. Folge ihm zu Reethe und halte ihn im ausbrechenden Kampf am Leben.",
	-- ["{npc:5395} and {npc:5412} stand in the post just west of {npc:11596}'s camp."] = "{npc:5395} und {npc:5412} stehen im Posten gleich westlich von {npc:11596}s Lager.",
	-- ["{npc:5395}: his {quest:1366}, from the same Maraudine"] = "{npc:5395}: {quest:1366}, von denselben Maraudine",
	-- ["{npc:6236}: Berserker Stance"] = "{npc:6236}: Berserkerhaltung",
	-- ["{npc:6791}: the last guide binds here, so this usually ticks at once"] = "{npc:6791}: Der letzte Guide bindet dich hier, daher ist das meist sofort abgehakt",
	-- ["{quest:1218}, for \"Swamp Eye\" Jarl"] = "{quest:1218}, für „Sumpfauge“ Jarl",
	-- ["{zone:1443}'s last quests and Alterac are 38-41. Still below 37.5 after Brackenwall's hand-ins? The Darkmist spiders and Lurkers (35-38) by the cavern north-west of the village are the closest: kill them until level 37.5."] = "Die letzten Quests von {zone:1443} und Alterac sind 38-41. Nach den Abgaben in Brackenwall noch unter 37,5? Die Spinnen und Lauerer der Darkmist (35-38) bei der Höhle nordwestlich des Dorfes sind am nächsten: Töte sie, bis du Stufe 37,5 bist.",
}
